import browser_workflows as b
import json, pathlib, sys, traceback
phase=sys.argv[1]
b.LOG=(b.ROOT/'evidence/logs'/('sheet07-'+phase+'.log')).open('w')

def box(selector):return b.js('(()=>{const r=document.querySelector('+json.dumps(selector)+').getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2};})()')

try:
    if phase=='desktop-mobile':
        b.ab('set','viewport',1280,800);b.reset();b.ab('click','#cell-A1');b.ab('press','1');b.ab('keyboard','type','2');b.ab('press','Tab');b.cells({'A1':'12','C1':'36','D1':'56','F1':'51'});assert b.ab('get','value','#address-input')=='B1'
        b.ab('press','F2');b.ab('press','Control+a');b.ab('keyboard','type','-2.5');b.ab('press','Enter');b.cells({'B1':'-2.5','C1':'-30','D1':'-10','F1':'-20.5'});assert b.ab('get','value','#address-input')=='B2';b.chart([-30,20,-10],[8,18,26]);b.screenshot('sheet07-desktop-keyboard-negative.png')
        b.goto('A1');b.ab('press','Shift+ArrowRight');b.ab('press','Shift+ArrowRight');b.ab('press','Shift+ArrowDown');assert b.ab('get','value','#address-input')=='A1:C2';assert b.ab('get','text','#numeric-count')=='6';assert b.ab('get','text','#numeric-sum')=='8.5'
        b.reset();b.ab('scrollintoview','#cell-A1');a=box('#cell-A1');z=box('#cell-C2');b.ab('mouse','move',round(a['x']),round(a['y']));b.ab('mouse','down','left');b.ab('mouse','move',round(z['x']),round(z['y']));b.ab('mouse','up','left');assert b.ab('get','value','#address-input')=='A1:C2';assert b.ab('get','text','#numeric-sum')=='40'
        b.edit('J2','0');assert b.js('document.querySelector("#chart-stage [data-address=J2]").getAttribute("aria-label")')=='Alpha · Plan: 0 · J2';assert float(b.js('document.querySelector("#chart-stage [data-address=J2]").getAttribute("height")'))>0
        b.reset();b.goto('L15');b.ab('press','1');b.ab('keyboard','type','23');assert b.ab('get','value','.cell-editor')=='123';b.ab('set','viewport',390,844);assert b.ab('get','value','.cell-editor')=='123';b.ab('keyboard','type','.45');b.ab('press','Enter');b.cells({'L15':'123.45'});assert b.raw('L15')=='123.45'
        b.goto('M15');b.fill('Formula bar','=L15*2');b.ab('set','viewport',1280,800);assert b.ab('get','value','#formula-input')=='=L15*2';b.ab('set','viewport',390,844);b.ab('type','#formula-input','+1');b.ab('press','Enter');b.cells({'M15':'247.9'});b.screenshot('sheet07-mobile-continuity.png')
        b.reset();b.ab('scroll','up',4000);b.screenshot('sheet07-mobile-workbook.png');assert b.js('document.documentElement.scrollWidth<=390')
        b.goto('F1');b.click('Copy');b.goto('F2');b.click('Paste');assert b.raw('F2')=='=$A2+B$1+$C$1';b.cells({'F2':'13'});b.click('Undo');b.cells({'F2':''})
        b.ab('scrollintoview','#chart-panel');b.click('Chart settings');b.fill('Chart title','Mobile plan');b.ab('select','#chart-type','line');b.ab('uncheck','#chart-legend');b.click('Save settings');assert b.ab('get','text','#chart-select')=='Mobile plan';b.chart([6,20,26],[8,18,26]);b.ab('scrollintoview','#chart-panel');b.screenshot('sheet07-mobile-chart-controls.png')
        p=b.download_json('mobile-workbook.json');b.import_text(p.read_text());b.cells({'C1':'6','D1':'26'});b.click('Import');b.fill('File contents','not json');b.click('Import workbook');assert 'Invalid JSON' in b.ab('get','text','#import-error');b.screenshot('sheet07-mobile-import-error.png');b.click('Close import')
        b.click('ƒx Formula reference');assert 'Formulas, made clear' in b.ab('get','text','#help-heading');b.click('Close formula reference');b.no_errors()
        b.ab('reload');b.cells({'A1':'2','F2':'','M15':''});assert b.ab('is','enabled','#undo')=='false';assert b.ab('get','text','#chart-select')=='Current vs Plan';b.edit('A1','5');b.click('Reset');b.cells({'A1':'2','C1':'6'});assert b.ab('is','enabled','#undo')=='false';assert b.ab('is','enabled','#redo')=='false';assert b.ab('is','enabled','#paste')=='false';b.no_errors();print('PASS desktop/mobile keyboard, pointer ranges, resize continuity, controls, zero/negative points, reload/reset')
    if phase=='direct-file':
        b.ab('frame','main');b.ab('set','viewport',1280,800);b.ab('network','har','start');b.ab('open',(b.ROOT/'index.html').as_uri());b.reset();b.cells({'C1':'6','C2':'20','D1':'26','E1':'10','F1':'11'});b.chart([6,20,26],[8,18,26]);b.edit('A1','5');b.cells({'C1':'15','D1':'35','F1':'23'});b.chart([15,20,35],[8,18,26]);p=b.download_json('direct-file-workbook.json');b.ab('download','#export-png',str(b.ROOT/'evidence/direct-file-chart.png'));b.ab('download','#export-svg',str(b.ROOT/'evidence/direct-file-chart.svg'))
        b.import_text('label,value\nalpha,2\nliteral,=1+1','csv');b.cells({'B2':'2','B3':'=1+1'});b.click('Undo');b.cells({'C1':'15','D1':'35'});b.screenshot('sheet07-direct-file.png');b.no_errors();b.ab('reload');b.cells({'A1':'2','C1':'6'});assert b.ab('is','enabled','#undo')=='false';b.ab('network','har','stop',str(b.ROOT/'evidence/logs/direct-file.har'));print('PASS direct-file editing/import/undo/downloads/reload')
    if phase=='opaque-frame':
        b.ab('frame','main');b.ab('set','viewport',1280,800);b.ab('network','har','start');b.ab('open','http://127.0.0.1:8765/evidence/opaque-frame.html');b.ab('frame','#studio-frame');b.ab('wait','#reset');b.reset()
        result=b.js('(()=>{let storage, parentAccess;try{void localStorage;storage="allowed";}catch(e){storage=e.name;}try{void parent.document;parentAccess="allowed";}catch(e){parentAccess=e.name;}return {origin:self.origin,storage,parentAccess};})()');assert result=={'origin':'null','storage':'SecurityError','parentAccess':'SecurityError'},result;print('Sandbox:',result)
        b.cells({'C1':'6','D1':'26','F1':'11'});b.goto('A1');b.ab('press','5');b.ab('press','Enter');b.cells({'C1':'15','D1':'35','F1':'23'});b.chart([15,20,35],[8,18,26]);b.click('Undo');b.goto('F1');b.click('Copy');b.goto('F2');b.click('Paste');assert b.raw('F2')=='=$A2+B$1+$C$1';b.cells({'F2':'13'})
        p=b.download_json('opaque-frame-workbook.json');b.ab('download','#export-svg',str(b.ROOT/'evidence/opaque-frame-chart.svg'));b.ab('download','#export-png',str(b.ROOT/'evidence/opaque-frame-chart.png'))
        b.import_text('label,value\n"alpha, beta",2\n"line\nbreak",=1+1','csv');b.cells({'A2':'alpha, beta','B2':'2','A3':'line\nbreak','B3':'=1+1'});assert b.ab('get','text','#chart-count')=='0';b.click('Import');b.ab('upload','#import-file',str(p));b.ab('wait','--fn','document.getElementById("import-text").value.includes("spreadsheet-chart-studio")');b.click('Import workbook');b.cells({'C1':'6','F2':'13'});b.click('Undo');b.cells({'B3':'=1+1','F2':''});b.click('Redo');b.cells({'C1':'6','F2':'13'});b.screenshot('sheet07-opaque-frame.png');b.no_errors();b.click('Reset');b.cells({'F2':'','D1':'26'});assert b.ab('is','enabled','#undo')=='false';b.ab('frame','main');b.ab('reload');b.ab('frame','#studio-frame');b.ab('wait','#reset');b.cells({'C1':'6','F2':''});b.no_errors();b.ab('network','har','stop',str(b.ROOT/'evidence/logs/opaque-frame.har'));b.ab('frame','main');print('PASS opaque-origin scripts/downloads-only iframe, storage/parent blocked, keyboard/internal copy/text+file imports/undo/downloads/reset/reload')
except Exception:
    b.LOG.write(traceback.format_exc());b.screenshot('sheet07-'+phase+'-failure.png');raise
finally:b.LOG.close()
